+		return p_msaa;
+	}
+
+	RD::TextureFormat tf;
+	tf.format = p_format;
+	tf.usage_bits = p_usage_bits;
+	tf.samples = msaa_to_samples(p_msaa);
+	RD::TextureSamples samples = RD::get_singleton()->texture_get_nearest_supported_samples(tf);
